61	    pub fn new(engine: &Engine) -> Result<Interpreter, OutOfMemory> {
62	        let ret = Interpreter {
63	            pulley: StoreBox::new(VmState {
64	                vm: Vm::with_stack(engine.config().max_wasm_stack),
65	                resume_at_pc: None,
